import {ActionList, ActionMenu, Button, Label, Pagination, Spinner} from '@primer/react'
import {CheckIcon} from '@primer/octicons-react'
import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemDescriptionItem} from '@github-ui/list-view/ListItemDescriptionItem'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import type {Organization} from '../../types'
import styles from './CopilotOrganizationAccessList.module.css'
import pluralize from 'pluralize'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {clsx} from 'clsx'
import {CopilotOrganizationUpgradePlanDialog} from './CopilotOrganizationUpgradePlanDialog'
import {CopilotOrganizationDowngradePlanDialog} from './CopilotOrganizationDowngradePlanDialog'
import {capitalizePlan} from '../../utils/string-utils'
import {CopilotOrganizationBulkDisableAccessDialog} from './CopilotOrganizationBulkDisableAccessDialog'
import {useCheckboxSelection} from '@github-ui/licensing-common/hooks/useCheckboxSelection'
import {usePlanChangeConfirmationDialog} from '../../hooks/use-plan-change-confirmation-dialog'
import {CopilotAccessListPlanOptions} from '../../utils/copilot-plan-options'
import {usePagination} from '../../hooks/use-pagination'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {Blankslate} from '@primer/react/experimental'
import {useState, useEffect} from 'react'

export interface CopilotOrganizationAccessListProps {
  // this prop is used in CopilotAccessList
  // eslint-disable-next-line @eslint-react/no-unused-props
  setOpenGrantAccessDialog: (arg0: boolean) => void
  pageSize?: number
  searchQuery?: string
  isTrial: boolean
}

// Ranking the plans to determine a downgrade/upgrade
const planRanks: Record<string, number> = {
  disabled: 0,
  business: 1,
  enterprise: 2,
}

export function CopilotOrganizationAccessList(props: CopilotOrganizationAccessListProps) {
  const {basePath} = useNavigation()
  const [isSmallViewport, setIsSmallViewport] = useState(false)

  // Check viewport width for responsive behavior
  useEffect(() => {
    const checkViewportWidth = () => {
      const sm = 544
      const md = 768
      const lg = 888
      const width = window.innerWidth
      setIsSmallViewport(width < sm || (width >= md && width <= lg))
    }

    checkViewportWidth()

    const resizeObserver = new ResizeObserver(() => {
      checkViewportWidth()
    })

    resizeObserver.observe(document.body)

    return () => resizeObserver.disconnect()
  }, [])

  const {
    results: organizations,
    loading,
    isEmpty,
    fetchCompleted,
  } = useEnterpriseCopilotAccessFetch<'organizations'>({
    basePath,
    searchQuery: props.searchQuery || '',
    searchType: 'organizations',
    withAccess: true,
  })

  /** Dialog management */
  const {dialogState, openDialog, closeDialog} = usePlanChangeConfirmationDialog<{
    orgId?: number
    orgIds?: number[]
    oldPlan: string
    newPlan: string
  }>()

  const handlePlanChange = async (organization: Organization, option: {text: string; value: string}) => {
    if (organization.copilotPlan !== option.value) {
      const oldPlanRank = planRanks[organization.copilotPlan]
      const newPlanRank = planRanks[option.value]

      if (oldPlanRank === undefined || newPlanRank === undefined) {
        throw new Error(`Invalid plan detected`)
      }

      const dialogType = newPlanRank > oldPlanRank ? 'upgrade' : 'downgrade'
      openDialog(dialogType, {
        orgId: organization.id,
        oldPlan: organization.copilotPlan,
        newPlan: option.value,
      })
    }
  }

  const handleBulkPlanChange = async (orgsToChange: Organization[], option: {text: string; value: string}) => {
    if (option.value === 'disabled') {
      openDialog('bulk-disable', {
        orgIds: orgsToChange.map(org => org.id),
        oldPlan: '',
        newPlan: option.value,
      })
    }
  }

  const renderDialog = () => {
    if (!dialogState.data) return null

    switch (dialogState.type) {
      case 'upgrade':
        if (!dialogState.data.orgId) return null
        return (
          <CopilotOrganizationUpgradePlanDialog
            oldPlan={dialogState.data.oldPlan}
            newPlan={dialogState.data.newPlan}
            orgId={dialogState.data.orgId}
            closeDialog={closeDialog}
          />
        )

      case 'downgrade':
        if (!dialogState.data.orgId) return null
        return (
          <CopilotOrganizationDowngradePlanDialog
            oldPlan={dialogState.data.oldPlan}
            newPlan={dialogState.data.newPlan}
            orgId={dialogState.data.orgId}
            closeDialog={closeDialog}
          />
        )

      case 'bulk-disable':
        if (!dialogState.data.orgIds || dialogState.data.orgIds.length === 0) return null
        return <CopilotOrganizationBulkDisableAccessDialog orgIds={dialogState.data.orgIds} closeDialog={closeDialog} />

      default:
        return null
    }
  }

  /** Set up pagination */
  const {
    currentPage,
    totalPages,
    paginatedItems: paginatedOrganizations,
    navigateToPage,
  } = usePagination(organizations, {pageSize: props.pageSize || 20})

  /** Checkbox management for bulk org selection */
  const {
    selectedItems: selectedOrganizations,
    handleSelectItem: handleSelectOrganization,
    handleSelectAll,
  } = useCheckboxSelection(paginatedOrganizations, (org: Organization) => org.id)
  let mainContent
  let pagination
  let showBorder = true

  if (loading) {
    mainContent = (
      <Blankslate>
        <Blankslate.Description>
          <Spinner size="medium" />
        </Blankslate.Description>
      </Blankslate>
    )
  } else {
    if (fetchCompleted) {
      if (isEmpty) {
        mainContent = (
          <Blankslate>
            <Blankslate.Heading>No organizations with access</Blankslate.Heading>
            <Blankslate.Description>
              Organizations that have been granted access to Copilot Business or Copilot Enterprise will be visible here
            </Blankslate.Description>
          </Blankslate>
        )
      } else {
        showBorder = false
        mainContent = (
          <ListView
            title="Organizations"
            isSelectable={!props.isTrial}
            singularUnits="organization"
            pluralUnits="organizations"
            totalCount={organizations.length}
            selectedCount={selectedOrganizations.size}
            metadata={
              <ListViewMetadata
                title={
                  selectedOrganizations.size > 0
                    ? `${selectedOrganizations.size} ${pluralize('organization', selectedOrganizations.size)} selected`
                    : `${pluralize('organization', organizations.length, true)}`
                }
                onToggleSelectAll={handleSelectAll}
                actionsLabel="Actions"
                actions={
                  selectedOrganizations.size > 0 && !props.isTrial
                    ? [
                        {
                          key: 'remove-bulk-access',
                          render(isOverflowMenu) {
                            const selectedOrgs = organizations.filter(org => selectedOrganizations.has(org.id))

                            return isOverflowMenu ? (
                              <ActionList.Item
                                id="button:remove-bulk-access"
                                onSelect={() =>
                                  handleBulkPlanChange(selectedOrgs, {text: 'Disabled', value: 'disabled'})
                                }
                              >
                                Remove access
                              </ActionList.Item>
                            ) : (
                              <Button
                                id="button:remove-bulk-access"
                                variant="danger"
                                className={styles.bulkDisableButton}
                                onClick={() =>
                                  handleBulkPlanChange(selectedOrgs, {text: 'Disabled', value: 'disabled'})
                                }
                              >
                                Remove access
                              </Button>
                            )
                          },
                        },
                      ]
                    : []
                }
              />
            }
            className="border border-muted rounded-2"
            data-testid="licensing-copilot-organization-access-list-view"
          >
            {paginatedOrganizations.map(organization => (
              <ListItem
                key={organization.id}
                isSelected={selectedOrganizations.has(organization.id)}
                onSelect={() => handleSelectOrganization(organization.id)}
                title={
                  <ListItemTitle
                    value={organization.login}
                    href={organization.orgUrl}
                    trailingBadges={
                      organization.expirationDate
                        ? [
                            <Label key="expiration" variant="attention" size="small">
                              {organization.copilotCanBeReenabled
                                ? `Expires on ${organization.expirationDate}`
                                : `Downgrades on ${organization.expirationDate}`}
                            </Label>,
                          ]
                        : undefined
                    }
                  />
                }
                secondaryActions={
                  isSmallViewport ? (
                    <ListItemActionBar
                      label="Organization actions"
                      staticMenuActions={(organization.copilotCanBeReenabled
                        ? CopilotAccessListPlanOptions.filter(option =>
                            [organization.previousPlan, organization.copilotPlan].includes(option.value),
                          )
                        : CopilotAccessListPlanOptions
                      ).map(option => ({
                        key: option.value,
                        render: () => (
                          <div style={{maxWidth: '320px'}}>
                            <ActionList.Item
                              inactiveText={
                                props.isTrial
                                  ? option.value === organization.copilotPlan
                                    ? ''
                                    : 'Unavailable during a trial'
                                  : ''
                              }
                              selected={organization.copilotPlan === option.value}
                              onSelect={() => handlePlanChange(organization, option)}
                              data-testid={`org-copilot-plan-${organization.id}-${option.value
                                .replace('_', '-')
                                .toLowerCase()}`}
                            >
                              <ActionList.LeadingVisual>
                                {organization.copilotPlan === option.value ? (
                                  <CheckIcon />
                                ) : (
                                  <span style={{width: 'var(--base-size-16)'}} />
                                )}
                              </ActionList.LeadingVisual>
                              <span
                                className={clsx(option.value === 'disabled' ? 'color-fg-danger' : 'font-weight-normal')}
                              >
                                {option.text}
                              </span>
                              <p className={'color-fg-muted mt-1'}>{option.subtext}</p>
                            </ActionList.Item>
                          </div>
                        ),
                      }))}
                    />
                  ) : (
                    <ActionMenu>
                      <ActionMenu.Button inactive={props.isTrial} className={styles.topRightButton}>
                        <span className="color-fg-muted">Copilot: </span>
                        {capitalizePlan(organization.copilotPlan)}
                      </ActionMenu.Button>
                      <ActionMenu.Overlay style={{maxWidth: '320px'}}>
                        <ActionList selectionVariant="single">
                          {(organization.copilotCanBeReenabled
                            ? CopilotAccessListPlanOptions.filter(option =>
                                [organization.previousPlan, organization.copilotPlan].includes(option.value),
                              )
                            : CopilotAccessListPlanOptions
                          ).map(option => (
                            <ActionList.Item
                              inactiveText={
                                props.isTrial
                                  ? option.value === organization.copilotPlan
                                    ? ''
                                    : 'Unavailable during a trial'
                                  : ''
                              }
                              key={option.value}
                              selected={organization.copilotPlan === option.value}
                              onSelect={() => handlePlanChange(organization, option)}
                              data-testid={`org-copilot-plan-${organization.id}-${option.value
                                .replace('_', '-')
                                .toLowerCase()}`}
                            >
                              <span
                                className={clsx(option.value === 'disabled' ? 'color-fg-danger' : 'font-weight-normal')}
                              >
                                {organization.copilotCanBeReenabled && option.value !== 'disabled' ? (
                                  <>Re-enable {option.text}</>
                                ) : (
                                  option.text
                                )}
                              </span>
                              <p className={'color-fg-muted mt-1'}>{option.subtext}</p>
                            </ActionList.Item>
                          ))}
                        </ActionList>
                      </ActionMenu.Overlay>
                    </ActionMenu>
                  )
                }
              >
                <ListItemLeadingContent>
                  <ListItemLeadingVisual>
                    <GitHubAvatar src={organization.avatarUrl} size={16} square />
                  </ListItemLeadingVisual>
                </ListItemLeadingContent>

                <ListItemMainContent>
                  <ListItemDescription>
                    <ListItemDescriptionItem>
                      {`${pluralize('license', organization.licenseCount, true)} assigned`}
                    </ListItemDescriptionItem>
                  </ListItemDescription>
                </ListItemMainContent>
              </ListItem>
            ))}
          </ListView>
        )

        if (totalPages > 1) {
          pagination = (
            <div className="tmp-mt-3 d-flex flex-justify-center">
              <Pagination
                currentPage={currentPage}
                pageCount={totalPages}
                onPageChange={(_, newPage) => navigateToPage(newPage)}
              />
            </div>
          )
        }
      }
    }
  }

  return (
    <>
      <div className={showBorder ? styles.emptyContainer : ''}>
        {mainContent}
        {pagination}
        {renderDialog()}
      </div>
    </>
  )
}
