import {CopilotUsageSummary} from '@github-ui/licensing-common/components/CopilotUsageSummary'
import {CopilotPaymentSummary} from '@github-ui/licensing-common/components/CopilotPaymentSummary'
import {SubPageLayout} from '@github-ui/licensing-common/components/SubPageLayout'
import {SummarySection} from '@github-ui/licensing-common/components/SummarySection'
import type {Sku} from '@github-ui/licensing-common/copilot-types'

import {CopilotAccessList} from './components/CopilotAccessList'
import {CopilotDangerZone} from './components/CopilotDangerZone'
import {CopilotLicensingHeader} from './components/CopilotLicensingHeader'
import {CopilotOrganizationGeneralAccessDropdown} from './components/organizations/CopilotOrganizationGeneralAccessDropdown'

export interface CopilotDetailsProps {
  copilotDetails: {
    skus: Sku[]
    billingTermEndDate: string
    totalCost: number
    enablementSetting: string
    accessibleOrganizationCount: number
    enabledBusinessTeamCount: number
    enabledAllMembersCount: number
    isTrial: boolean
    atMaxCopilotLicenseCount?: boolean
  }
  slug: string
  enterpriseContactUrl: string
  isStafftools: boolean
  isTeams: boolean
  isCopilotBusinessTeamFlagEnabled: boolean
  policiesPath?: string
}

export function CopilotDetails({copilotDetails, ...props}: CopilotDetailsProps) {
  return (
    <SubPageLayout
      enterpriseContactUrl={props.enterpriseContactUrl}
      isStafftools={props.isStafftools}
      isTeams={props.isTeams}
      slug={props.slug}
      header={<CopilotLicensingHeader policiesPath={props.policiesPath} />}
      containerProps={{'data-testid': 'licensing-copilot-details'}}
    >
      <>
        <div className="tmp-mb-4">
          <SummarySection
            isError={false}
            isLoading={false}
            summaries={[
              <CopilotUsageSummary skus={copilotDetails.skus} headingLevel="h2" key="usage-summary" />,
              <CopilotPaymentSummary
                isTrial={copilotDetails.isTrial}
                billingTermEndDate={copilotDetails.billingTermEndDate}
                skus={copilotDetails.skus}
                totalCost={copilotDetails.totalCost}
                headingLevel="h2"
                key="payment-summary"
              />,
            ]}
          />
        </div>
        <CopilotOrganizationGeneralAccessDropdown
          enablementSetting={copilotDetails.enablementSetting}
          isTrial={copilotDetails.isTrial}
        />
        <CopilotAccessList
          accessibleOrganizationCount={copilotDetails.accessibleOrganizationCount}
          enabledBusinessTeamCount={copilotDetails.enabledBusinessTeamCount}
          enabledAllMembersCount={copilotDetails.enabledAllMembersCount}
          isCopilotBusinessTeamFlagEnabled={props.isCopilotBusinessTeamFlagEnabled}
          atMaxCopilotLicenseCount={copilotDetails.atMaxCopilotLicenseCount}
          isTrial={copilotDetails.isTrial}
        />
        <CopilotDangerZone />
      </>
    </SubPageLayout>
  )
}
